// The dialogue of the activity scenes beyond the first wording of each topic (data/activity-scene-lines.js): more questions for every family of topics, the attitude of the people who ask
// (favourable, neutral, against), and the PROFILES of the activities that are not what the room of their kind would suggest — a rally is not a meeting of associations, a talk with another party is
// not a meeting of one's own branch, an intergroup in Brussels is not the Council of Ministers. A profile gives the activity its own people, questions, ways in, moves and room, so that what is said
// fits who says it and where. Every text is a pair [Italian, English] with no free part (the phrase-book reads `ALL_PAIRS`); nothing here decides a result.
// The engine (core/activity-scenes.js) chooses among the questions by the memory of the career (the wording met least recently first), so the same encounter does not repeat the same words.

import { F as FEMALE, M as MALE, registerRoleGenders } from '../core/avatar.js?v=20261125-7';
const P = (it, en) => [it, en];
// a move of a profile: { id, fn, stat, label, when? } like the moves of data/activity-scene-moves.js
const M = (id, fn, stat, it, en, when = null) => ({ id, fn, stat, label: [it, en], ...(when ? { when } : {}) });

